    /**
     * {@inheritdoc}
     *
     * @return CompletePackage[]|\Generator
     */
    public static function find(callable $callable): \Generator
    {
        $instance = self::getInstance();

        foreach ($instance->getIterator() as $package) {
            if ($callable($package) === true) {
                yield $package;
            }
        }
    }

